    review.update(group_i={"prompt":"original descriptive practice; verified descriptive PYQ search remains open","word_counts":group['answers'][0]['answer_words'],"substantive_review":"Matched introduction, substantive claims, counterweights and conclusion across languages; removed unrelated qualifications and filler; inserted precise statutory limitations where needed","quality_limits":"One model answer per chapter does not establish full descriptive coverage"},guide_source_matching="Precise prepared chapter headings, saved GBK page locators and partial/absent qualifications recorded in Source-qualifications.html",academic_corrections=["Permanent Lok Adalat post-conciliation merits power qualified to non-offence disputes under section22C(8)"] if cid=='7.4.4' else ["Removal majority stated as both total-membership and present-and-voting conditions; political disagreement alone insufficient"])
